SET NAMES utf8;

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_asignaciones_saldo_pendiente_corregida` AS select `asignacion`.`asignaciones`.`nro_unidad` AS `NroUn.`,`asignacion`.`meses`.`mes` AS `Mes`,`asignacion`.`asignaciones`.`año` AS `Año`,`asignacion`.`grupos`.`grupo` AS `Modelo`,`asignacion`.`modelos`.`modelo` AS `Versión`,`asignacion`.`asignaciones`.`nro_orden` AS `NroOrden`,`asignacion`.`asignaciones`.`interno` AS `Interno`,`asignacion`.`asignaciones`.`chasis` AS `Chasis`,`asignacion`.`asignaciones`.`cliente` AS `Cliente`,`asignacion`.`usuarios`.`nombre` AS `Asesor`,`asignacion`.`sucursales`.`sucursal` AS `Sucursal`,`asignacion`.`asignaciones`.`fec_reserva` AS `Reserva`,`asignacion`.`asignaciones`.`fec_arribo` AS `Arribo`,`asignacion`.`asignaciones`.`fec_despacho` AS `Despacho`,`asignacion`.`asignaciones`.`estado_tasa` AS `Confirmada TASA`,`asignacion`.`asignaciones`.`cancelada` AS `Cancelada`,`asignacion`.`asignaciones`.`pagado` AS `pagado_tasa`,`asignacion`.`modelos`.`costo` AS `Costo TASA`,`reservas_suma_montos`.`monto` AS `Operacion`,`reservas_suma_pagos`.`pagos` AS `Pagos`,(coalesce(`reservas_suma_montos`.`monto`,0) - coalesce(`reservas_suma_pagos`.`pagos`,0)) AS `Saldo`,`asignacion`.`sucursales`.`idsucursal` AS `idsucursal`,`asignacion`.`asignaciones`.`estado_reserva` AS `EstadoReserva` from (((((((`asignacion`.`asignaciones` join `asignacion`.`grupos` on((`asignacion`.`asignaciones`.`id_grupo` = `asignacion`.`grupos`.`idgrupo`))) join `asignacion`.`modelos` on((`asignacion`.`asignaciones`.`id_modelo` = `asignacion`.`modelos`.`idmodelo`))) join `asignacion`.`usuarios` on((`asignacion`.`asignaciones`.`id_asesor` = `asignacion`.`usuarios`.`idusuario`))) join `asignacion`.`meses` on((`asignacion`.`asignaciones`.`id_mes` = `asignacion`.`meses`.`idmes`))) left join `asignacion`.`reservas_suma_montos` on((`asignacion`.`asignaciones`.`nro_unidad` = `reservas_suma_montos`.`nrounidad`))) left join `asignacion`.`reservas_suma_pagos` on((`asignacion`.`asignaciones`.`nro_unidad` = `reservas_suma_pagos`.`nrounidad`))) join `asignacion`.`sucursales` on((`asignacion`.`usuarios`.`idsucursal` = `asignacion`.`sucursales`.`idsucursal`))) where ((`asignacion`.`asignaciones`.`guardado` = 1) and (`asignacion`.`asignaciones`.`borrar` = 0) and (`asignacion`.`asignaciones`.`entregada` = 0) and (`asignacion`.`asignaciones`.`id_negocio` = 1) and (`asignacion`.`asignaciones`.`estado_tasa` = 1) and (not((`asignacion`.`asignaciones`.`nro_orden` like 'TPA%'))) and ((`asignacion`.`asignaciones`.`año` < year(curdate())) or ((`asignacion`.`asignaciones`.`año` = year(curdate())) and (`asignacion`.`asignaciones`.`id_mes` <= month(curdate()))))) order by `asignacion`.`asignaciones`.`año`,`asignacion`.`asignaciones`.`id_mes`;

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`usernavicat`@`%` SQL SECURITY DEFINER VIEW `view_asignaciones_saldo_pendiente_corregida_no_llegadas` AS select `asignacion`.`sucursales`.`idsucursal` AS `IdSucursal`,`asignacion`.`sucursales`.`sucursal` AS `Sucursal`,sum((coalesce(`reservas_suma_montos`.`monto`,0) - coalesce(`reservas_suma_pagos`.`pagos`,0))) AS `Saldo` from ((((`asignacion`.`asignaciones` join `asignacion`.`usuarios` on((`asignacion`.`asignaciones`.`id_asesor` = `asignacion`.`usuarios`.`idusuario`))) join `asignacion`.`sucursales` on((`asignacion`.`usuarios`.`idsucursal` = `asignacion`.`sucursales`.`idsucursal`))) left join `asignacion`.`reservas_suma_montos` on((`asignacion`.`asignaciones`.`nro_unidad` = `reservas_suma_montos`.`nrounidad`))) left join `asignacion`.`reservas_suma_pagos` on((`asignacion`.`asignaciones`.`nro_unidad` = `reservas_suma_pagos`.`nrounidad`))) where ((`asignacion`.`asignaciones`.`guardado` = 1) and (`asignacion`.`asignaciones`.`borrar` = 0) and (`asignacion`.`asignaciones`.`entregada` = 0) and (`asignacion`.`asignaciones`.`id_negocio` = 1) and (`asignacion`.`asignaciones`.`estado_tasa` = 1) and (`asignacion`.`asignaciones`.`pagado` = 0) and (not((`asignacion`.`asignaciones`.`nro_orden` like 'TPA%'))) and ((`asignacion`.`asignaciones`.`año` < year(curdate())) or ((`asignacion`.`asignaciones`.`año` = year(curdate())) and (`asignacion`.`asignaciones`.`id_mes` <= month(curdate()))))) group by `asignacion`.`sucursales`.`idsucursal`,`asignacion`.`sucursales`.`sucursal` order by `asignacion`.`sucursales`.`sucursal`;

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`usernavicat`@`%` SQL SECURITY DEFINER VIEW `view_asignaciones_saldo_pendiente_corregida_en_viaje` AS select `s`.`idsucursal` AS `IdSucursal`,`s`.`sucursal` AS `Sucursal`,coalesce(sum((coalesce(`rm`.`monto`,0) - coalesce(`rp`.`pagos`,0))),0) AS `Saldo` from ((((`asignacion`.`sucursales` `s` left join `asignacion`.`usuarios` `u` on((`u`.`idsucursal` = `s`.`idsucursal`))) left join `asignacion`.`asignaciones` `a` on(((`a`.`id_asesor` = `u`.`idusuario`) and (`a`.`guardado` = 1) and isnull(`a`.`fec_arribo`) and (`a`.`borrar` = 0) and (`a`.`entregada` = 0) and (`a`.`estado_tasa` = 1) and (`a`.`pagado` = 1) and (`a`.`id_negocio` = 1) and (`a`.`chasis` is not null) and (`a`.`chasis` <> '') and (not((`a`.`nro_orden` like 'TPA%'))) and ((`a`.`año` < year(curdate())) or ((`a`.`año` = year(curdate())) and (`a`.`id_mes` <= month(curdate()))))))) left join `asignacion`.`reservas_suma_montos` `rm` on((`a`.`nro_unidad` = `rm`.`nrounidad`))) left join `asignacion`.`reservas_suma_pagos` `rp` on((`a`.`nro_unidad` = `rp`.`nrounidad`))) group by `s`.`idsucursal`,`s`.`sucursal` order by `s`.`sucursal`;

