s`.`año` < year(curdate())) or ((`asignacion`.`asignaciones`.`año` = year(curdate())) and (`asignacion`.`asignaciones`.`id_mes` <= month(curdate()))))) group by `asignacion`.`sucursales`.`idsucursal`,`asignacion`.`sucursales`.`sucursal` order by `asignacion`.`sucursales`.`sucursal`;

